// Skin colour variants on the phone (#843, src/lib/skin-families.ts): a base
// skin plus an optional tint (`omb-skin-tint`: a colour, a duo-tone or a
// mood) and, for a colour, how far it reaches (`omb-skin-depth`: the accent
// only, or the whole surface). The desktop lays `data-skin-tint` and
// `data-skin-depth` over `data-skin`; the phone lays the same tokens over
// the base skin's (`DesktopSkins.table`) before it derives its palette.
//
// Only the solid tokens travel: a duo-tone's gradient and a mood's glow
// draw as their first colour here. The Windows editions of Hibou 98 are not
// listed (Hibou 98 is desktop only on iOS), and the textures
// (`omb-skin-texture`) have no phone drawing.
//
// `SkinTints.table` is copied from src/styles.css, src/styles/skin-depth.css,
// skin-duo.css and skin-ambiance.css; `SkinTintsTests` re-reads them when
// they are reachable, so the two cannot drift silently.
import Foundation

/// A colour, duo-tone or mood laid over a base skin (`SKIN_TINT_IDS`, the
/// phone's share of them).
public enum SkinTint: String, CaseIterable, Sendable, Codable {
    case red, pink, blue, green, yellow
    case aurore, ocean, neon, foret
    case cyberpunk, sunset, nordic, candy

    /// The plain colours: the only tints with a depth (`SKIN_COLOR_TINTS`).
    public var isColor: Bool {
        switch self {
        case .red, .pink, .blue, .green, .yellow: true
        default: false
        }
    }
}

/// How far a colour reaches (`SKIN_DEPTHS`): the accent only, or the whole surface.
public enum SkinDepth: String, CaseIterable, Sendable, Codable {
    case accent, full
}

/// The keys the desktop stores the variant under (shared/user-preferences.ts).
public enum SkinTintKeys {
    public static let tint = "omb-skin-tint"
    public static let depth = "omb-skin-depth"
    public static let texture = "omb-skin-texture"
    public static let variants = "omb-skin-variants"
}

public enum SkinTints {
    /// The tint a stored value names on this skin, or nil: unknown, or one
    /// the skin's family has no variant for (`normalizeWorn`).
    public static func tint(_ raw: String?, on skin: SkinID) -> SkinTint? {
        guard let raw, let tint = SkinTint(rawValue: raw.trimmingCharacters(in: .whitespaces)) else { return nil }
        return table["\(skin.rawValue)|\(tint.rawValue)"] == nil ? nil : tint
    }

    /// `omb-skin-depth`: "full" or the accent only (absent, unknown).
    public static func depth(_ raw: String?) -> SkinDepth {
        raw.flatMap(SkinDepth.init(rawValue:)) ?? .accent
    }

    /// The tokens a tint (and, for a colour, the full depth) lays over the
    /// base skin's; empty when the skin has no such variant.
    public static func overrides(_ skin: SkinID, tint: SkinTint?, depth: SkinDepth) -> [String: String] {
        guard let tint, let layer = table["\(skin.rawValue)|\(tint.rawValue)"] else { return [:] }
        var out = layer
        if depth == .full, tint.isColor, let full = table["\(skin.rawValue)|\(tint.rawValue)|full"] {
            // the full block re-hues the surfaces; the accent family stays the tint block's
            for (key, value) in full where layer[key] == nil { out[key] = value }
        }
        return out
    }

