public extension DesktopSkins {
    /// The base skin's tokens with a tint laid over them.
    static func tokens(_ id: SkinID, tint: SkinTint?, depth: SkinDepth) -> DesktopSkinTokens? {
        guard let base = table[id.rawValue] else { return nil }
        let layer = SkinTints.overrides(id, tint: tint, depth: depth)
        guard !layer.isEmpty else { return tokens(id) }
        return tokens(raw: base.merging(layer) { _, over in over })
    }
}

public extension SkinPalette {
    /// A skin with the computer's tint (`omb-skin-tint`, `omb-skin-depth`).
    /// The phone's own skins (Black, Dim) and Hibou 98 take none.
    static func of(_ id: SkinID, tint: SkinTint?, depth: SkinDepth) -> SkinPalette {
        guard let tint, SkinTints.tint(tint.rawValue, on: id) != nil,
              let tokens = DesktopSkins.tokens(id, tint: tint, depth: depth) else { return of(id) }
        var palette = derived(id, tokens)
        palette.tint = tint
        palette.depth = tint.isColor ? depth : .accent
        return palette
    }
}
